import { readFileSync } from "fs"
import { AwsError } from "../common"

// Request decoding and response encoding for the EC2 "ec2" protocol, driven by the botocore service model
// in data/aws/ec2-model.json (generated by getec2model.py).

interface MemberRef {
  shape: string
  locationName?: string
  queryName?: string
}

interface Shape {
  type: string
  members?: Record<string, MemberRef>
  member?: MemberRef
  required?: string[]
  enum?: string[]
  flattened?: boolean
}

interface Model {
  apiVersion: string
  operations: Record<string, { input?: string; output?: string }>
  shapes: Record<string, Shape>
}

let model: Model | undefined

export function ec2Model(): Model {
  model ??= JSON.parse(readFileSync('data/aws/ec2-model.json').toString())
  return model!
}

export const EC2_NAMESPACE = 'http://ec2.amazonaws.com/doc/2016-11-15/'

const capitalize = (s: string) => s[0].toUpperCase() + s.slice(1)
const lowerFirst = (s: string) => s[0].toLowerCase() + s.slice(1)

// ---------------------------------------------------------------------------
// request: flat form parameters -> object
// ---------------------------------------------------------------------------

// EC2 query names are queryName, else the capitalized locationName, else the member name.
function queryName(name: string, ref: MemberRef): string {
  if (ref.queryName) {
    return ref.queryName
  }
  return ref.locationName ? capitalize(ref.locationName) : name
}

function decodeShape(shapeName: string, key: string, params: Map<string, string>, keys: string[]): unknown {
  const shape = ec2Model().shapes[shapeName]
  switch (shape.type) {
    case 'structure': {
      const result: Record<string, unknown> = {}
      for (const [name, ref] of Object.entries(shape.members ?? {})) {
        const value = decodeShape(ref.shape, `${key}.${queryName(name, ref)}`, params, keys)
        if (value !== undefined) {
          result[name] = value
        }
      }
      return Object.keys(result).length ? result : undefined
    }
    case 'list': {
      const indexes = new Set<number>()
      for (const k of keys) {
        if (k.startsWith(`${key}.`)) {
          const index = /^\d+/.exec(k.slice(key.length + 1))
          if (index) {
            indexes.add(Number(index[0]))
          }
        }
      }
      const list = [...indexes].sort((a, b) => a - b)
        .map(i => decodeShape(shape.member!.shape, `${key}.${i}`, params, keys))
        .filter(v => v !== undefined)
      return list.length ? list : undefined
    }
    default: {
      const raw = params.get(key)
      return raw === undefined ? undefined : decodeScalar(shape, raw)
    }
  }
}

function decodeScalar(shape: Shape, raw: string): unknown {
  switch (shape.type) {
    case 'boolean':
      return raw === 'true'
    case 'integer':
    case 'long':
    case 'double':
    case 'float':
      return Number(raw)
    default:
      return raw
  }
}

export function decodeInput(action: string, form: URLSearchParams): Record<string, any> {
  const operation = ec2Model().operations[action]
  if (!operation?.input) {
    return {}
  }
  const params = new Map<string, string>()
  form.forEach((value, key) => params.set(key, value))
  const keys = [...params.keys()]
  const input = ec2Model().shapes[operation.input]
  const result: Record<string, any> = {}
  for (const [name, ref] of Object.entries(input.members ?? {})) {
    const value = decodeShape(ref.shape, queryName(name, ref), params, keys)
    if (value !== undefined) {
      result[name] = value
    }
  }
  validateInput(input, result)
  return result
}

function validateInput(input: Shape, value: Record<string, any>) {
  for (const required of input.required ?? []) {
    if (value[required] === undefined) {
      throw new AwsError('MissingParameter', `The request must contain the parameter ${required}`)
    }
  }
  for (const [name, ref] of Object.entries(input.members ?? {})) {
    const allowed = ec2Model().shapes[ref.shape].enum
    if (allowed && typeof value[name] === 'string' && !allowed.includes(value[name])) {
      throw new AwsError('InvalidParameterValue', `Value (${value[name]}) for parameter ${lowerFirst(ref.locationName ?? name)} is invalid.`)
    }
  }
}

// ---------------------------------------------------------------------------
// response: object -> XML
// ---------------------------------------------------------------------------

export function escapeXml(text: string): string {
  return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
}

function encodeShape(ref: MemberRef, element: string, value: unknown, out: string[]) {
  if (value === undefined || value === null) {
    return
  }
  const shape = ec2Model().shapes[ref.shape]
  switch (shape.type) {
    case 'structure': {
      out.push(`<${element}>`)
      encodeMembers(shape, value as Record<string, unknown>, out)
      out.push(`</${element}>`)
      return
    }
    case 'list': {
      const items = value as unknown[]
      const itemName = shape.member?.locationName ?? 'member'
      if (shape.flattened) {
        for (const item of items) {
          encodeShape(shape.member!, element, item, out)
        }
      } else if (!items.length) {
        out.push(`<${element}/>`)
      } else {
        out.push(`<${element}>`)
        for (const item of items) {
          encodeShape(shape.member!, itemName, item, out)
        }
        out.push(`</${element}>`)
      }
      return
    }
    case 'timestamp': {
      const date = value instanceof Date ? value : new Date(value as string | number)
      out.push(`<${element}>${date.toISOString()}</${element}>`)
      return
    }
    default:
      out.push(`<${element}>${escapeXml(String(value))}</${element}>`)
  }
}

function encodeMembers(shape: Shape, value: Record<string, unknown>, out: string[]) {
  for (const [name, ref] of Object.entries(shape.members ?? {})) {
    encodeShape(ref, ref.locationName ?? name, value[name], out)
  }
}

export function encodeOutput(action: string, result: unknown, requestId: string): string {
  const out = [
    `<?xml version="1.0" encoding="UTF-8"?>\n<${action}Response xmlns="${EC2_NAMESPACE}">`,
    `<requestId>${requestId}</requestId>`
  ]
  const outputShape = ec2Model().operations[action]?.output
  if (outputShape) {
    encodeMembers(ec2Model().shapes[outputShape], (result ?? {}) as Record<string, unknown>, out)
  } else {
    out.push('<return>true</return>')
  }
  out.push(`</${action}Response>`)
  return out.join('')
}

export function encodeError(code: string, message: string, requestId: string): string {
  return `<?xml version="1.0" encoding="UTF-8"?>\n<Response><Errors><Error><Code>${escapeXml(code)}</Code><Message>${escapeXml(message)}</Message></Error></Errors><RequestID>${requestId}</RequestID></Response>`
}
